exercises.solution:
class Zaehlwerk {
  private int stand = 0;
  public synchronized void erhoehe() { stand++; }
  public int getStand() { return stand; }
}

class ZaehlThread extends Thread {
  private Zaehlwerk z;
  public ZaehlThread(Zaehlwerk z) { this.z = z; }
  public void run() {
    for (int i = 0; i < 1000; i++) z.erhoehe();
  }
}

class SyncZaehler {
  public static void main(String[] args) throws InterruptedException {
    Zaehlwerk z = new Zaehlwerk();
    ZaehlThread[] t = new ZaehlThread[3];
    for (int i = 0; i < 3; i++) {
      t[i] = new ZaehlThread(z);
      t[i].start();
    }
    for (int i = 0; i < 3; i++) {
      t[i].join();
    }
    System.out.println("Endstand: " + z.getStand());
  }
}

