import java.io.*;
import java.net.*;

class EchoDienst extends Thread {
  private ServerSocket server;
  public EchoDienst(ServerSocket server) { this.server = server; }
  public void run() {
    try {
      Socket verbindung = server.accept();
      InputStream  in  = verbindung.getInputStream();
      OutputStream out = verbindung.getOutputStream();
      int c;
      while ( (c = in.read()) != -1 ) out.write(c);
      verbindung.close();
    }
    catch (IOException e) { System.out.println("Server: " + e.toString()); }
  }
}

class MiniEcho {
  public static void main(String[] args) throws Exception {
    ServerSocket server = new ServerSocket(0);
    int port = server.getLocalPort();
    EchoDienst dienst = new EchoDienst(server);
    dienst.start();

    Socket client = new Socket("localhost", port);
    OutputStream out = client.getOutputStream();
    BufferedReader in = new BufferedReader( new InputStreamReader(client.getInputStream()) );
    out.write("OFP\r\n".getBytes());
    out.flush();
    System.out.println("Echo: " + in.readLine());
    client.close();
    dienst.join();
    server.close();

    InetAddress addr = InetAddress.getByName("localhost");
    System.out.println("Adresse: " + addr.getHostAddress());
  }
}

