import java.io.*;

class Konto implements Serializable {
  String inhaber;
  double saldo;
  transient double zinsen;          // transient = wird NICHT serialisiert
  public Konto(String inhaber, double saldo) {
    this.inhaber = inhaber;
    this.saldo   = saldo;
    this.zinsen  = 99.9;
  }
}

class SerTest {
  public static void main(String[] args) throws Exception {
    Konto k = new Konto("Meier", 100.0);
    ObjectOutputStream oos = new ObjectOutputStream( new FileOutputStream("konto.ser") );
    oos.writeObject(k);
    k.saldo = 500.0;
    oos.writeObject(k);             // Achtung: kein reset() dazwischen!
    oos.close();

    ObjectInputStream ois = new ObjectInputStream( new FileInputStream("konto.ser") );
    Konto k1 = (Konto) ois.readObject();
    Konto k2 = (Konto) ois.readObject();
    ois.close();

    System.out.println(k1.saldo);
    System.out.println(k2.saldo);
    System.out.println(k1 == k2);
    System.out.println(k1.zinsen);
  }
}
